  uninstall() {
    this.disposables.forEach(dispose => dispose());
    this.disposables.length = 0;
  }

  now(): number {
    this._replayLogOnce();
    // Sync real time to support calling Date.now() in a loop.
    this._syncRealTime();
    return this._now.time;
  }

  install(time: number) {
    this._replayLogOnce();
    this._innerInstall(asWallTime(time));
